consume(codeHash): ConsumeResult {
  const e = live.codes.peek(codeHash);
  if (!e) return { kind: "missing" };
  if (e.used) return { kind: "reused", code: e.code };
  commit({ op: "code.used", codeHash });
  return { kind: "ok", code: e.code };
}

