function replay(text: string, apply: (r: unknown) => void): { replayed: number; droppedTornLine: boolean } {
  const lines = text.split("\n");
  const tail = lines.pop() ?? "";
  lines.forEach((line, i) => {
    let rec: unknown;
    try { rec = JSON.parse(line); } catch { throw new Error(`line ${i + 1} is corrupt`); }
    apply(rec);
  });
  return { replayed: lines.length, droppedTornLine: tail !== "" };
}
